page(
 slug="kit-urgence-enfants-ecole", emoji="🎒",
 title="Kit urgence 72 h et enfants à l'école : règles et réflexes",
 desc="Comprendre le PPMS à l'école, ne pas aller chercher ses enfants en crise, parler aux enfants et adapter le kit d'urgence 72 h aux besoins du foyer.",
 h1="Kit d'urgence 72 h et enfants à l'école : préparer sa famille",
 lead="En cas de crise majeure, l'école applique le PPMS et prend en charge les élèves. N'allez pas chercher vos enfants sans consigne des autorités : vous risqueriez de vous exposer au danger et d'encombrer les axes et les secours. Préparez votre kit d'urgence 72 h en pensant aux enfants et expliquez-leur calmement les consignes.",
 source="SGDSN (Guide Tous responsables, 20/11/2025), Ministère de l'Éducation nationale (PPMS), Géorisques, info.gouv.fr",
 nav_label="Enfants et école", nav_emoji="🎒",
 sections=[
  ("ppms-ecole", "Le PPMS à l'école : pourquoi ne pas aller chercher ses enfants", """<p>Chaque école ou établissement dispose d'un <strong>plan particulier de mise en sûreté (PPMS)</strong> adapté aux risques locaux (inondation, accident industriel, tempête, menace sécuritaire). Les personnels encadrent les élèves et appliquent le confinement ou l'évacuation selon les consignes des autorités.</p>
<p>En cas d'alerte ou de crise, <strong>n'allez pas chercher votre enfant à l'école</strong> tant que les autorités ne l'autorisent pas. Se déplacer sous la pluie, la fumée ou l'alerte augmente le risque d'accident et bloque l'accès des secours.</p>
<ul class="check">
 <li><strong>Laissez les lignes libres :</strong> n'appelez pas l'école en boucle afin de ne pas saturer le téléphone ni gêner la gestion de crise.</li>
 <li><strong>Suivez les canaux officiels :</strong> écoutez la radio, surveillez <a href="https://www.info.gouv.fr/risques" target="_blank" rel="noopener">info.gouv.fr</a> et les alertes préfectorales ou FR-Alert.</li>
 <li><strong>Vérifiez les consignes locales :</strong> consultez le <a href="plan-familial-mise-en-surete.html">plan familial de mise en sûreté</a> et les informations transmises par l'établissement.</li>
</ul>"""),
  ("parler-enfants", "Parler des risques aux enfants sans les inquiéter", """<p>Parler de préparation à la maison aide les enfants à comprendre les règles sans vivre dans la peur. Utilisez des mots simples et des repères concrets, adaptés à leur âge.</p>
<ol class="steps-list">
 <li><strong>Expliquez l'utilité du kit :</strong> présentez le sac comme un outil pratique pour tenir trois jours en cas de coupure d'eau ou d'électricité, au même titre qu'un détecteur de fumée.</li>
 <li><strong>Montrez les gestes d'alerte :</strong> expliquez le son des sirènes ou des notifications d'urgence et rappelez qu'il faut écouter les adultes et les consignes officielles.</li>
 <li><strong>Entraînez-vous calmement :</strong> repérez ensemble où se trouve le kit et vérifiez qu'ils savent allumer une lampe de poche sans jouer avec les équipements.</li>
</ol>
<p class="note">Évitez de relayer des rumeurs ou des images anxiogènes devant les plus jeunes : appuyez-vous uniquement sur des informations vérifiées.</p>"""),
  ("ajouts-kit-enfants", "Adapter le kit d'urgence 72 h aux enfants", """<p>Le socle du <a href="kit-de-survie-72h.html">kit d'urgence 72 h</a> couvre les besoins de base (eau, alimentation sans cuisson, lampe, radio à piles, trousse de secours, papiers). Ajoutez des éléments adaptés à l'âge de chaque enfant.</p>
<div class="cards">
 <div class="card"><h3><span class="ic" aria-hidden="true">🧸</span>Réconfort et calme</h3><ul><li>Un doudou ou petit objet rassurant</li><li>Jeux calmes, crayons ou carnet sans pile</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">🧥</span>Vêtements et hygiène</h3><ul><li>Vêtements chauds et chaussures adaptées</li><li>Lingettes, mouchoirs, couches ou rechanges</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">🩺</span>Santé et repères</h3><ul><li>Traitement éventuel et copie de l'ordonnance</li><li>Carte avec noms et téléphones des proches</li></ul></div>
</div>"""),
 ],
 faq=[
  ("Dois-je aller chercher mon enfant à l'école lors d'une alerte ?", "Non, sauf consigne expresse des autorités. L'école met en œuvre son PPMS pour protéger les élèves sur place, et vos déplacements peuvent vous mettre en danger ou gêner les secours."),
  ("Comment savoir si mon enfant est en sécurité pendant une crise ?", "Suivez les informations officielles diffusées par les autorités, la préfecture ou l'établissement, et gardez les lignes téléphoniques disponibles pour les urgences. N'allez pas sur place sans autorisation."),
  ("Que mettre dans le kit d'urgence pour un enfant ?", "Prévoyez de l'eau, des aliments sans cuisson adaptés à son âge, des vêtements chauds, un éventuel traitement médical avec ordonnance, de quoi s'occuper calmement et une fiche avec les coordonnées des parents."),
  ("Comment aborder le sujet avec un jeune enfant ?", "Restez calme et factuel. Expliquez que le kit sert à attendre tranquillement que tout rentre dans l'ordre et que les adultes suivent des règles prévues à l'avance."),
 ],
 related=["plan-familial-mise-en-surete","kit-de-survie-72h","kit-urgence-bebe","fr-alert-que-faire"],
)

page(
 slug="kit-urgence-personne-agee", emoji="👵",
 title="Kit urgence 72 h et personne âgée : santé, CCAS et météo",
 desc="Préparer l'autonomie 72 h d'une personne âgée : traitements, ordonnances, registre communal du CCAS, canicule, grand froid et téléassistance.",
 h1="Kit d'urgence 72 h et personne âgée : anticiper les crises",
 lead="Pour une personne âgée, une coupure de courant, une canicule ou un grand froid demandent une anticipation particulière. Préparez un kit d'urgence 72 h incluant les traitements et ordonnances, inscrivez-vous sur le registre communal auprès du CCAS et vérifiez la téléassistance.",
 source="SGDSN (Guide Tous responsables, 20/11/2025), service-public.gouv.fr, Santé publique France, préfectures",
 nav_label="Personne âgée", nav_emoji="👵",
 sections=[
  ("sante-documents", "Traitements, ordonnances et essentiels du kit", """<p>En situation d'urgence ou d'isolement, la continuité des soins et l'accès aux documents médicaux sont prioritaires. Complétez le <a href="kit-de-survie-72h.html">kit d'urgence 72 h</a> avec des éléments adaptés à la santé de la personne.</p>
<ul class="check">
 <li><strong>Médicaments et ordonnances :</strong> réserve de traitement en cours selon les recommandations médicales, copies des ordonnances et liste des allergies ou pathologies.</li>
 <li><strong>Santé et confort visuel :</strong> paire de lunettes de secours, piles pour appareils auditifs si besoin, trousse de premiers secours et thermomètre.</li>
 <li><strong>Eau, repas et chaleur :</strong> eau potable en bouteilles, aliments prêts à consommer sans cuisson, vêtements chauds, couverture de survie et lampe facile à allumer.</li>
</ul>"""),
  ("registre-ccas-teleassistance", "Registre communal du CCAS et téléassistance", """<p>Les communes tiennent un <strong>registre nominatif des personnes vulnérables</strong> (notamment les personnes âgées et isolées ou en situation de handicap) via le centre communal d'action sociale (CCAS) ou la mairie.</p>
<ol class="steps-list">
 <li><strong>Demandez l'inscription :</strong> l'inscription est volontaire et gratuite ; elle peut être faite par la personne concernée ou par un proche, souvent sur <a href="https://www.service-public.gouv.fr" target="_blank" rel="noopener">service-public.gouv.fr</a> ou en mairie.</li>
 <li><strong>Comprenez le dispositif :</strong> en cas de déclenchement d'un plan d'alerte (canicule, grand froid ou autre crise locale), les services municipaux ou le CCAS peuvent organiser un suivi ou une prise de contact.</li>
 <li><strong>Vérifiez la téléassistance :</strong> testez régulièrement le fonctionnement du dispositif d'alerte à domicile et prévoyez une solution de secours en cas de coupure électrique prolongée.</li>
</ol>"""),
  ("canicule-grand-froid", "Adapter la préparation à la canicule et au grand froid", """<p>Les températures extrêmes aggravent rapidement les fragilités liées à l'âge. Adaptez les réflexes quotidiens selon la saison et les vigilances officielles.</p>
<div class="cards">
 <div class="card"><h3><span class="ic" aria-hidden="true">☀️</span>Fortes chaleurs et canicule</h3><ul><li>Boire de l'eau régulièrement et garder le logement frais</li><li>Voir <a href="canicule-que-faire.html">canicule : que faire</a> et surveiller les proches</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">❄️</span>Grand froid et gel</h3><ul><li>Maintenir une température intérieure sûre sans risque d'intoxication</li><li>Voir <a href="vague-de-froid-que-faire.html">vague de froid : que faire</a> et éviter les sorties risquées</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">🔌</span>Panne d'électricité</h3><ul><li>Garder lampe et radio à piles à portée de main</li><li>Voir <a href="coupure-electricite-que-faire.html">coupure d'électricité : que faire</a></li></ul></div>
</div>"""),
 ],
 faq=[
  ("Comment inscrire une personne âgée sur le registre communal ?", "La démarche se fait auprès du CCAS ou de la mairie, souvent via les services en ligne de service-public.gouv.fr. L'inscription est gratuite et facultative, et peut être demandée par la personne ou un proche."),
  ("Que prévoir côté médical dans le kit d'urgence ?", "Rangez dans une pochette étanche les copies des ordonnances, la liste des traitements et allergies, les coordonnées du médecin traitant, une paire de lunettes de secours et les piles ou consommables nécessaires."),
  ("Que faire si la téléassistance fonctionne sur secteur lors d'une coupure ?", "Vérifiez auprès de l'opérateur de téléassistance l'autonomie de secours du boîtier en cas de panne électrique et conservez un téléphone mobile chargé ainsi qu'une liste de numéros utiles sur papier."),
  ("À quel moment contacter les proches ou les secours ?", "Appelez un proche ou les voisins référents dès que le besoin d'aide se fait sentir, et composez le 15, le 18 ou le 112 (ou le 114 par SMS ou visio si besoin) en cas d'urgence vitale ou de détresse."),
 ],
 related=["canicule-que-faire","vague-de-froid-que-faire","coupure-electricite-que-faire","kit-de-survie-72h"],
)

page(
 slug="kit-urgence-handicap", emoji="♿",
 title="Kit urgence 72 h et handicap : 114, matériel et aidants",
 desc="Préparer une crise de 72 h en situation de handicap : numéro d'urgence 114 (SMS, visio, appli), matériel médical électrique et coordination avec les aidants.",
 h1="Kit d'urgence 72 h et handicap : 114, matériel et aidants",
 lead="En situation de handicap, préparer 72 heures d'autonomie exige d'adapter le kit et la communication d'urgence. Connaissez le 114 (accessible par SMS, visio et application), anticipez le matériel médical dépendant de l'électricité et organisez un relais clair avec vos aidants.",
 source="SGDSN (Guide Tous responsables, 20/11/2025), Ministère de l'Intérieur / Urgence 114, handicap.gouv.fr, service-public.gouv.fr",
 nav_label="Handicap et 114", nav_emoji="♿",
 sections=[
  ("alerter-114", "Le 114 : alerter les secours par SMS, visio ou application", """<p>Le <strong>114</strong> est le numéro national d'urgence gratuit, disponible 24h/24 et 7j/7, pour les personnes ayant des difficultés à entendre ou à parler, qu'elles soient victimes ou témoins. Il permet aussi d'alerter discrètement lorsque parler est impossible.</p>
<ul class="check">
 <li><strong>Canaux d'accès :</strong> envoi d'un <strong>SMS au 114</strong>, ou appel en visioconférence et tchat via l'application 114 ou le site officiel <a href="https://www.info.urgence114.fr" target="_blank" rel="noopener">info.urgence114.fr</a>.</li>
 <li><strong>Transmission aux secours :</strong> les opérateurs orientent vers les services de secours adaptés (Samu, pompiers, police ou gendarmerie).</li>
 <li><strong>Préparation sur le téléphone :</strong> enregistrez le 114 à l'avance et notez votre adresse, votre étage ou accès et vos besoins essentiels pour gagner du temps en cas d'urgence.</li>
</ul>"""),
  ("materiel-electrique-kit", "Matériel médical électrique et adaptation du kit", """<p>Une coupure de courant ou une évacuation peut perturber les équipements médicaux ou d'aide à la mobilité. Intégrez ces points à votre <a href="kit-de-survie-72h.html">kit d'urgence 72 h</a> et à votre organisation quotidienne.</p>
<ol class="steps-list">
 <li><strong>Identifiez les appareils sensibles :</strong> listez tout matériel médical ou d'assistance fonctionnant sur secteur ou batterie et vérifiez son autonomie sans courant.</li>
 <li><strong>Préparez consommables et rechanges :</strong> conservez des piles adaptées, câbles, dispositifs de secours manuels si applicable, traitements et copies d'ordonnances dans une pochette étanche.</li>
 <li><strong>Anticipez l'évacuation :</strong> prévoyez l'accès sans ascenseur en cas de panne électrique ou de consigne de sécurité, et gardez à portée de main les aides techniques indispensables.</li>
</ol>"""),
  ("aidants-relais", "Coordonner les aidants et l'entraide de proximité", """<p>Un plan clair entre la personne concernée, les aidants familiaux ou professionnels et les voisins évite l'isolement pendant les premières 72 heures.</p>
<div class="cards">
 <div class="card"><h3><span class="ic" aria-hidden="true">🤝</span>Rôles des aidants</h3><ul><li>Définir qui vérifie le kit et les stocks</li><li>Préciser qui contacter en cas d'absence ou de crise</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">📋</span>Fiche d'urgence</h3><ul><li>Traitements, allergies et consignes de soins</li><li>Numéros des proches, aidants et services</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">🏘️</span>Voisinage et mairie</h3><ul><li>Voir <a href="entraide-voisins-crise.html">entraide entre voisins en crise</a></li><li>S'inscrire au registre communal via le CCAS si concerné</li></ul></div>
</div>"""),
 ],
 faq=[
  ("Comment fonctionne le 114 en cas d'urgence ?", "Le 114 est un service d'urgence gratuit et national ouvert 24h/24, accessible par SMS, application dédiée et visioconférence ou tchat via info.urgence114.fr, pour les personnes sourdes, malentendantes, aphasiques ou dans l'impossibilité de parler."),
  ("Que prévoir si un appareil médical a besoin d'électricité ?", "Vérifiez l'autonomie sur batterie de l'équipement, consultez votre médecin ou prestataire de santé sur la conduite à tenir en cas de coupure prolongée et gardez des piles ou consommables de rechange prêts à l'emploi."),
  ("Comment organiser la coordination avec les aidants ?", "Répartissez par écrit les tâches (réapprovisionnement, contact en cas d'alerte, aide à l'évacuation) et conservez une fiche à jour accessible aux personnes de confiance."),
  ("Peut-on utiliser le 114 si l'on n'est pas sourd ou malentendant ?", "Oui, le 114 est également utile lorsqu'une situation impose de rester silencieux ou qu'il est impossible de parler à voix haute."),
 ],
 related=["coupure-electricite-que-faire","entraide-voisins-crise","kit-de-survie-72h","plan-familial-mise-en-surete"],
)

page(
 slug="kit-urgence-voiture", emoji="🚗",
 title="Kit urgence voiture : gilet, triangle, loi Montagne et neige",
 desc="Gilet et triangle obligatoires, équipements hiver loi Montagne (1er nov - 31 mars), affaires utiles dans le coffre et réflexes si vous êtes bloqué dans la neige.",
 h1="Kit d'urgence en voiture : obligations, hiver et neige",
 lead="En voiture, le gilet de haute visibilité et le triangle de présignalisation sont obligatoires. Du 1er novembre au 31 mars dans les zones concernées, des équipements hiver s'ajoutent. Complétez votre véhicule avec quelques affaires utiles et sachez réagir si vous êtes bloqué dans la neige.",
 source="service-public.gouv.fr (Code de la route et équipements hiver), Météo-France, préfectures",
 nav_label="Kit voiture", nav_emoji="🚗",
 sections=[
  ("obligations-loi-montagne", "Gilet, triangle et équipements hiver (loi Montagne)", """<p>Le Code de la route impose des équipements de base à bord et, selon les zones et la saison, des équipements hivernaux.</p>
<table class="tbl">
 <thead><tr><th>Équipement</th><th>Règle et période</th><th>Usage principal</th></tr></thead>
 <tbody>
  <tr><td><strong>Gilet de haute visibilité</strong></td><td>Obligatoire à bord du véhicule</td><td>À porter avant de sortir du véhicule en cas d'arrêt d'urgence</td></tr>
  <tr><td><strong>Triangle de présignalisation</strong></td><td>Obligatoire à bord du véhicule</td><td>Signaler un véhicule immobilisé sur la chaussée (sauf mise en danger manifeste)</td></tr>
  <tr><td><strong>Équipements hiver</strong></td><td>Du 1er novembre au 31 mars dans les zones désignées par arrêté préfectoral</td><td>Pneus hiver (3PMSF) ou chaînes/chaussettes selon les règles en vigueur</td></tr>
 </tbody>
</table>
<p class="note">Vérifiez les communes concernées par l'obligation hivernale et la signalisation locale sur <a href="https://www.service-public.gouv.fr" target="_blank" rel="noopener">service-public.gouv.fr</a> avant de prendre la route.</p>"""),
  ("affaires-coffre-habitacle", "Affaires utiles à garder à bord", """<p>Gardez le gilet accessible depuis l'habitacle plutôt qu'au fond d'un coffre chargé. Ajoutez quelques équipements simples pour faire face à une attente prolongée ou à une panne.</p>
<ul class="check">
 <li><strong>Visibilité et sécurité :</strong> gilet à portée de main (et idéalement un par occupant), lampe de poche, grattoir et produit lave-glace adapté au froid.</li>
 <li><strong>Chaleur, eau et énergie :</strong> vêtements chauds, couverture, bouteilles d'eau, encas non périssables et câble ou batterie de secours pour téléphone.</li>
 <li><strong>Secours et papiers :</strong> trousse de premiers secours, copie des documents d'assurance et de contact en cas de panne.</li>
</ul>"""),
  ("bloque-neige", "Que faire si vous êtes bloqué dans la neige", """<p>Si la neige ou le verglas immobilise votre véhicule, adoptez des gestes prudents en attendant les secours ou le dégagement de la route.</p>
<ol class="steps-list">
 <li><strong>Signalez-vous et restez à l'abri :</strong> allumez les feux de détresse, portez votre gilet si vous devez sortir et restez dans l'habitacle sauf consigne contraire des autorités.</li>
 <li><strong>Vérifiez l'échappement :</strong> si le moteur tourne pour le chauffage, assurez-vous que le pot d'échappement n'est pas obstrué par la neige.</li>
 <li><strong>Économisez la batterie et informez-vous :</strong> limitez les consommations électriques inutiles, écoutez la radio et suivez les bulletins de <a href="https://vigilance.meteofrance.fr" target="_blank" rel="noopener">Météo-France</a> ou de la préfecture.</li>
</ol>
<p class="note">Consultez aussi <a href="vague-de-froid-que-faire.html">vague de froid : que faire</a> et <a href="tempete-que-faire.html">tempête : que faire</a> avant vos déplacements hivernaux.</p>"""),
 ],
 faq=[
  ("Le gilet jaune et le triangle sont-ils obligatoires dans toute voiture ?", "Oui, le gilet de haute visibilité et le triangle de présignalisation doivent être présents à bord du véhicule et utilisés en cas d'arrêt d'urgence selon les règles du Code de la route."),
  ("Quand s'appliquent les équipements hiver dans les zones concernées ?", "L'obligation d'équipements hivernaux dans les communes désignées par arrêté préfectoral s'applique du 1er novembre au 31 mars."),
  ("Que faire si je suis bloqué sur une route enneigée ?", "Restez à l'abri dans le véhicule, allumez les feux de détresse, vérifiez que l'échappement n'est pas bloqué par la neige, économisez la batterie et suivez les consignes officielles."),
  ("Faut-il garder de l'eau et de la nourriture dans la voiture ?", "Oui, quelques bouteilles d'eau et des aliments non périssables, accompagnés de vêtements chauds et d'une lampe, aident à patienter lors d'un blocage prolongé."),
 ],
 related=["vague-de-froid-que-faire","tempete-que-faire","kit-de-survie-72h","recharger-telephone-coupure-courant"],
)

page(
 slug="arnaque-kit-urgence-gratuit", emoji="🛡️",
 title="Arnaque au faux kit d'urgence gratuit : vérifier et signaler",
 desc="Faux « kit gratuit du gouvernement » par SMS ou site trompeur : comment vérifier et où signaler (33700, internet-signalement.gouv.fr). L'État ne vend aucun kit.",
 h1="Faux « kit d'urgence gratuit » : vérifier et signaler l'arnaque",
 lead="Les pouvoirs publics diffusent des guides et conseils gratuits sur les sites officiels en .gouv.fr, pas des « kits gratuits » via des liens douteux. Ne cliquez pas sur les liens suspects, ne payez pas de prétendus frais d'envoi et signalez les messages ou sites frauduleux au 33700 et sur internet-signalement.gouv.fr.",
 source="info.gouv.fr, SGDSN, CNIL, internet-signalement.gouv.fr, service-public.gouv.fr",
 nav_label="Arnaque faux kit", nav_emoji="🛡️",
 sections=[
  ("reperer-faux-kit", "Repérer les faux « kits gratuits du gouvernement »", """<p>Des messages, publications ou sites malveillants peuvent exploiter l'actualité de la préparation aux crises pour proposer un prétendu « kit d'urgence gratuit » contre des coordonnées bancaires ou personnelles.</p>
<ul class="check">
 <li><strong>Méfiez-vous de l'urgence artificielle :</strong> les messages trompeurs poussent souvent à cliquer vite ou à régler de petits frais de dossier ou de livraison.</li>
 <li><strong>Ne transmettez aucune donnée sensible :</strong> aucune démarche officielle de prévention ne vous demandera votre numéro de carte bancaire ou vos mots de passe par lien reçu par SMS.</li>
 <li><strong>Comparez avec les recommandations officielles :</strong> le <a href="kit-urgence-72h-gouvernement.html">kit d'urgence 72 h du gouvernement</a> se compose avec des objets courants du quotidien.</li>
</ul>"""),
  ("verifier-sources", "Vérifier l'adresse et les sources officielles", """<p>Avant de faire confiance à une information ou à un formulaire en ligne, vérifiez l'adresse exacte affichée dans votre navigateur et recoupez avec les portails publics.</p>
<ol class="steps-list">
 <li><strong>Vérifiez le nom de domaine :</strong> privilégiez les sites officiels de l'État comme <a href="https://www.info.gouv.fr/risques" target="_blank" rel="noopener">info.gouv.fr</a>, <a href="https://www.service-public.gouv.fr" target="_blank" rel="noopener">service-public.gouv.fr</a> ou le site de votre préfecture.</li>
 <li><strong>Ne cliquez pas depuis un message inconnu :</strong> ouvrez un nouvel onglet et tapez vous-même l'adresse du site officiel plutôt que de suivre un lien raccourci ou douteux.</li>
 <li><strong>Méfiez-vous des imitations :</strong> une lettre modifiée ou une adresse proche d'un site public peut dissimuler une page de collecte de données.</li>
</ol>"""),
  ("ou-signaler", "Où signaler un SMS ou un site frauduleux", """<p>Signaler une tentative de fraude aide à bloquer les numéros et à faire fermer les sites malveillants.</p>
<div class="cards">
 <div class="card"><h3><span class="ic" aria-hidden="true">📱</span>SMS frauduleux : 33700</h3><ul><li>Transférez le SMS suspect au <strong>33700</strong></li><li>Suivez la réponse automatique pour indiquer l'expéditeur</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">🌐</span>Site illicite : Pharos</h3><ul><li>Signalez l'adresse sur <a href="https://www.internet-signalement.gouv.fr" target="_blank" rel="noopener">internet-signalement.gouv.fr</a></li><li>Conservez capture d'écran, date et adresse du site</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">💳</span>Préjudice ou banque</h3><ul><li>Faites opposition immédiatement si vos données bancaires ont été saisies</li><li>Retrouvez les démarches sur <a href="https://www.service-public.gouv.fr" target="_blank" rel="noopener">service-public.gouv.fr</a></li></ul></div>
</div>"""),
 ],
 faq=[
  ("Le gouvernement distribue-t-il un kit d'urgence gratuit via un lien reçu par SMS ou sur un site inconnu ?", "Non. Les informations officielles sur la préparation aux risques et au kit 72 h sont publiées gratuitement sur les sites officiels comme info.gouv.fr et service-public.gouv.fr."),
  ("Comment signaler un SMS suspect proposant un faux kit gratuit ?", "Transférez le message au 33700 sans cliquer sur le lien qu'il contient, puis suivez les instructions reçues pour compléter le signalement."),
  ("Où signaler un faux site imitant un service officiel ?", "Vous pouvez signaler le site frauduleux sur internet-signalement.gouv.fr (portail officiel de signalement des contenus illicites) et consulter service-public.gouv.fr pour les démarches en cas de préjudice."),
  ("Que faire si j'ai déjà saisi mes coordonnées bancaires sur un site suspect ?", "Contactez immédiatement votre banque pour faire opposition et conservez les preuves (adresse du site, date, captures d'écran) pour vos démarches."),
 ],
 related=["kit-urgence-72h-gouvernement","guide-tous-responsables-resume","questions-reponses-kit-urgence","kit-de-survie-72h"],
)

page(
 slug="plan-familial-mise-en-surete", emoji="🗺️",
 title="Plan familial de mise en sûreté (PFMS) : rôles, RDV et contacts",
 desc="Organiser son plan familial de mise en sûreté : qui fait quoi, point de rendez-vous, contacts utiles et articulation avec le kit d'urgence 72 h.",
 h1="Plan familial de mise en sûreté (PFMS) : organiser son foyer",
 lead="Un plan familial de mise en sûreté (PFMS) permet à chaque membre du foyer de savoir quoi faire si une crise survient à la maison, au travail ou à l'école. Définissez qui fait quoi, fixez un point de rendez-vous, listez les contacts essentiels et reliez le plan à votre kit d'urgence 72 h.",
 source="Géorisques, SGDSN (Guide Tous responsables, 20/11/2025), Code de la sécurité intérieure, info.gouv.fr",
 nav_label="Plan familial (PFMS)", nav_emoji="🗺️",
 sections=[
  ("qui-fait-quoi", "Qui fait quoi en cas d'alerte ou de crise", """<p>En situation d'urgence, répartir les rôles à l'avance évite la précipitation et les oublis. Chaque membre du foyer doit connaître les consignes selon l'endroit où il se trouve.</p>
<ul class="check">
 <li><strong>À la maison :</strong> répartissez les gestes simples (prendre le <a href="kit-de-survie-72h.html">kit d'urgence 72 h</a>, fermer portes et fenêtres ou couper les fluides si nécessaire et sans danger, aider les personnes fragiles).</li>
 <li><strong>À l'école ou au travail :</strong> chacun applique les consignes locales (PPMS à l'école, consignes de l'employeur ou des autorités) sans déplacement dangereux.</li>
 <li><strong>Écoute des alertes :</strong> désignez qui consulte les canaux officiels (radio à piles, <a href="https://www.georisques.gouv.fr" target="_blank" rel="noopener">Géorisques</a>, <a href="https://www.info.gouv.fr/risques" target="_blank" rel="noopener">info.gouv.fr</a>, FR-Alert) et évite de relayer des rumeurs.</li>
</ul>"""),
  ("point-de-rendez-vous", "Choisir un point de rendez-vous et un lieu de repli", """<p>Selon la nature de l'événement, les autorités peuvent demander de rester confiné à l'abri ou d'évacuer un secteur. Prévoyez des repères clairs sur papier.</p>
<ol class="steps-list">
 <li><strong>Identifiez les risques locaux :</strong> consultez <a href="https://www.georisques.gouv.fr" target="_blank" rel="noopener">Géorisques</a> et les informations de votre commune pour connaître les risques du territoire.</li>
 <li><strong>Définissez des points de regroupement :</strong> prévoyez un point de rendez-vous proche en cas d'évacuation locale et une solution de repli chez un proche hors zone si nécessaire.</li>
 <li><strong>Gardez le plan accessible :</strong> imprimez votre PFMS et glissez-le avec votre kit afin de pouvoir le lire même sans réseau ni batterie.</li>
</ol>"""),
  ("contacts-essentiels", "Carnet de contacts et numéros d'urgence sur papier", """<p>En cas de coupure de courant ou de réseau saturé, un répertoire uniquement numérique peut devenir inaccessible. Conservez une fiche écrite à jour.</p>
<div class="cards">
 <div class="card"><h3><span class="ic" aria-hidden="true">🚨</span>Numéros d'urgence</h3><ul><li>15 (Samu), 18 (Pompiers), 17 (Police/Gendarmerie)</li><li>112 (urgence européen) et 114 (SMS/visio/appli)</li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">👨‍👩‍👧</span>Proches et référents</h3><ul><li>Membres du foyer et personne de contact hors secteur</li><li>Voisins ou aidants selon <a href="entraide-voisins-crise.html">entraide voisins en crise</a></li></ul></div>
 <div class="card"><h3><span class="ic" aria-hidden="true">🏥</span>Santé et services</h3><ul><li>Médecin traitant, pharmacie et traitements</li><li>Mairie, CCAS ou coordonnées d'assistance utiles</li></ul></div>
</div>"""),
 ],
 faq=[
  ("À quoi sert un plan familial de mise en sûreté (PFMS) ?", "Il aide les membres d'un foyer à savoir quoi faire face à une crise majeure : répartir les premiers gestes, suivre les consignes officielles, se retrouver si besoin et garder les contacts utiles."),
  ("Pourquoi garder le plan et les numéros sur papier ?", "En cas de panne électrique, de batterie déchargée ou de réseau perturbé, une version imprimée reste lisible immédiatement."),
  ("Comment relier le PFMS au kit d'urgence 72 h ?", "Placez une copie du PFMS et de la liste de contacts dans votre kit d'urgence 72 h et vérifiez-les en même temps que le contenu du sac."),
  ("Où vérifier les risques autour de son logement ?", "Vous pouvez consulter georisques.gouv.fr, les informations de votre préfecture et les documents d'information de votre mairie."),
 ],
 related=["kit-urgence-enfants-ecole","kit-de-survie-72h","entraide-voisins-crise","kit-urgence-handicap"],
)


